export const matches = (
		str: string,
		regexp: string | RegExp
		): boolean => {

	if (typeof regexp === 'string') {
		return new RegExp(regexp).test(str)
	}
	else {
		return regexp.test(str)
	}
}

// ---------------------------------------------------------------------------

const similarWords = (
		word1: string,
		word2: string
		): boolean => {

	if (word1 === word2) {
		return true
	}

	// --- check if word2 is a regular expression within '{' and '}'
	const lMatches = word2.match(/^\{(.*)\}$/)
	if (defined(lMatches)) {
		// --- It's a regexp pattern
		const re = new RegExp(lMatches[1])
		return re.test(word1)
	}

	return false
}

// ---------------------------------------------------------------------------

const similarLines = (
		line1: string,
		line2: string
		): boolean => {

	const lWords1 = words(line1)
	const n = lWords1.length
	const lWords2 = words(line2)
	if (lWords2.length !== n) {
		return false
	}
	for (const i of range(n)) {
		if (!similarWords(lWords1[i], lWords2[i])) {
			return false
		}
	}
	return true
}

// ---------------------------------------------------------------------------

export const strHasPat = (
		str1: string,
		str2: string
		): boolean => {

	const lLines1 = str1.split('\n')
	const n = lLines1.length
	const lLines2 = str2.split('\n')
	if (lLines2.length !== n) {
		return false
	}
	for (const i of range(n)) {
		if (!similarLines(lLines1[i], lLines2[i])) {
			return false
		}
	}
	return true
}

// ---------------------------------------------------------------------------

export const anyMatches = (
		lStrings: string[],
		regexp: RegExp
		): boolean => {

	for (const s of lStrings) {
		if (matches(s, regexp)) {
			return true
		}
	}
	return false
}

// ---------------------------------------------------------------------------

export const allLinesIn = function*(
		block: string,
		includeNL: boolean = false
		): TIterator<string> {

	// --- remove any carriage return characters from block
	block = block.replaceAll('\r', '')

	let start = 0
	let end = block.indexOf('\n')
	while (end !== -1) {
		yield block.substring(start, (includeNL ? end+1 : end))
		start = end + 1
		end = block.indexOf('\n', start)
	}
	if (start < block.length) {
		yield block.substring(start)
	}
	return
}

