type DeepReadonly<T> = T extends Function | Date | RegExp | Map<any, any> | Set<any>
	? T
	: T extends object
	? { readonly [K in keyof T]: DeepReadonly<T[K]> }
	: T

export const deepFreeze = <T extends object,>(obj: T): DeepReadonly<T> => {

	for (const key in obj) {const value = obj[key];
		if (defined(value) && (typeof value === 'object') && !Object.isFrozen(value)) {
			deepFreeze(value)
		}
	}

	return Object.freeze(obj) as DeepReadonly<T>
}

// ---------------------------------------------------------------------------

export const working_deepFreeze = <T extends object,>(obj: T): DeepReadonly<T> => {

	Object.keys(obj).forEach((prop) => {
		const value = (obj as any)[prop]
		if (value && (typeof value === 'object') && !Object.isFrozen(value)) {
			deepFreeze(value)
		}
	}
		)

	return Object.freeze(obj) as DeepReadonly<T>
}

